mapper.select:
SELECT id FROM (
    SELECT id
    FROM project
    WHERE biz_no = #{bizNo}
      AND prj_identifier = #{prjIdentifier}
    ORDER BY id DESC
) WHERE ROWNUM = 1

mapper.update:
update project
